sys_ws_operation.operation_script:
(function process(request, response) {
    try {
        var attachmentSysId =
            request.queryParams.attachment_sys_id;

        var attachmentName =
            request.queryParams.attachment_name;

        if (gs.nil(attachmentSysId) && gs.nil(attachmentName)) {
            response.setStatus(400);
            response.setBody({
                error: 'Either attachment_sys_id or attachment_name is required.'
            });
            return;
        }

        if (!gs.nil(attachmentSysId) && !gs.nil(attachmentName)) {
            response.setStatus(400);
            response.setBody({
                error: 'Specify either attachment_sys_id or attachment_name, not both.'
            });
            return;
        }

        var service = new ProjectMCPAttachmentService();

        var result = service.getAttachment(
            attachmentSysId,
            attachmentName
        );

        if (!result.success) {
            response.setStatus(result.status || 500);

            gs.error(
                'project_mcp.get_attachment service error: ' +
                result.error
            );

            response.setBody({
                error: result.error
            });

            return;
        }

        response.setStatus(200);
        response.setBody(result.data);

    } catch (e) {
        gs.error(
            'project_mcp.get_attachment error: ' +
            e.message
        );

        response.setStatus(500);
        response.setBody({
            error: 'Internal error processing request'
        });
    }
})(request, response);
